wp:postmeta.wp:meta_value:
:is(.vc_row-no-padding,.wd-section-stretch-content-no-pd) .vc_row-fluid {
    margin-left: -15px !important;
}

.banner-section a.btn,
.banner-section-two a.btn {
    font-size: 16px;
    letter-spacing: 1px;
    padding: 15px 35px;
    background: linear-gradient(to left, #f0f0f000 50%, #000000 50%) right;
    background-size: 200% 100%;
    transition: 0.5s;
    border: 2px solid #000;
    border-radius: 3px;
    color: #000 !important;
}

.banner-section-two .wpb_column.vc_column_container.vc_col-sm-6,
.banner-section .wpb_column.vc_column_container.vc_col-sm-6 {
    align-items: center;
}

.banner-section a.btn:hover,
.banner-section-two a.btn:hover {
    background-position: left;
    color: #fff !important;
}

.hero-section .container.wd-slide-container.content-fixed {
    padding-top: 0;
}

.hero-section img.attachment-full.size-full {
    width: 70%;
}

.hero-section .wd-slider-pagin {
    bottom: 55px;
}


.banner-section h1.omniverse-title-container,
.banner-section-two h1.omniverse-title-container {
    font-size: 40px;
}

.banner-section-two .title-after_title,
.banner-section .title-after_title {
    font-size: 18px;
}

.title-after_title {
    font-size: 18px;
}

.main-page-wrapper {
    padding-top: 0 !important;
}

.testimonial-row p {
    font-size: 35px;
    text-align: center;
    color: #000;
}

.mc4wp-form-fields p {
    display: flex;
}

.wd-slider.wd-section-container .wd-slide-container {
    padding-inline: 7% !important;
}

.container.wd-slide-container.content-fixed{
    padding-bottom: 0;
}

@media (max-width: 767px) {
  :is(.vc_row-no-padding, .wd-section-stretch-content-no-pd) .vc_row-fluid {
    margin-right: -15px !important;
  }
}



.blog-sec img{
    height:300px;
    object-fit: cover;   
}

.latest-pro .products-tabs-title .wd-active {
  border-bottom: 2px solid;
}

